block=block.replace('https://raw.githubusercontent.com/intasan/gold-trading/main/evidence/dashboard-desktop.jpg',p['images'][0]['src']);s=s.replace(oldblock,block).replace('Concept / In Progress · 2026',p['kind']).replace('projects.js?v=20261103-acceptance','projects.js?v=20261104-runtime').replace('projects.js?v=20261104-gold','projects.js?v=20261104-runtime');f.write_text(s)
